import com.opensymphony.xwork2.ActionContext;
import org.apache.struts2.util.OgnlUtil;

public class Struts2VulnerableMultipart extends JakartaMultiPartRequest {
    @Override
    public void parse(HttpServletRequest request, String saveDir) {
        try {
            super.parse(request, saveDir);
        } catch (Exception e) {
            // 修复：禁止将 HTTP 头直接拼接到 OGNL 表达式
            String safeContentType = request.getHeader("Content-Type");
            if (safeContentType == null) {
                safeContentType = "application/octet-stream";
            }
            String errorMessage = "Error: " + safeContentType;
            OgnlContext ctx = (OgnlContext) ActionContext.getContext().getContextMap();
            try {
                // 修复：使用 OGNL 安全表达式，禁止直接求值用户可控字符串
                Object result = OgnlUtil.getValue(errorMessage, ctx, (Object) null);
                // ...
            } catch (Exception ignored) {}
